class ta_pcmd(object):
    ROBOT_LISTENER_API_VERSION = 2
    ROBOT_LIBRARY_SCOPE = 'GLOBAL'

    def __init__(self):
        self.logger = configure_logger('ta_pcmd.interface')
        self.message_awaited = None
        self.timeout = False
        self.plugin_already_loaded = False
        self.pcmd_collectors = []
        self.pcmd_servers = []
        self.technologies = []

    def configure_pcmd(self, ip=IP, port=PORT, technology='4G', asn1per_decoding=False,
                       tshark_interface=TSHARK_INTERFACE, clients=1, load_plugin=True):
        '''
        First, copies tshark nsetap dissector to tshark plugin folder,
        then starts Python PCMD server to which eNB connects and sends PCMD reports then
        starts tshark process with parameters. Tshark output will be used to collectd
        PCMD reports. This is the first thing to call after importing this library.

        :param ip:      IP address of the trace collection entity of 3rd Party Tool (in MTRACE MOC).
                        On this ip Python PCMD server will be started.
        :param port:    The Trace Port Number to be used for this Cell trace session while establishing
                        trace connection(TCP) towards 3rd Party Tool (in MTRACE MOC).
                        On this port Python server will wait for eNB connection.
        :param asn1per_decoding:    Enables decoding of NSETAP-X by ASN1PER decoder and enables yaml record verification
        :param tshark_interface: Enable change of tshark interface, by default is eth3
        :param clients: Allows multiple accepts for single ip/socket pair
        :param load_plugin: Allows to skip automatic plugin download, by default is set to True to load latest version
                            (current implementation behavior)
        :return: None.
        '''
        if _opt_bool(load_plugin) is True and not self.plugin_already_loaded:
            load_tshark_plugin_via_wireshark_script(technology=technology)
            self.plugin_already_loaded = True
        else:
            self.logger.debug('Not loading plugin again.Already loaded once.')
        if technology not in self.technologies:
            self.technologies.append(technology)
        self._start_pcmd_collector(ip=ip, port=port, technology=technology,
                                   asn1per_decoding=_opt_bool(asn1per_decoding),
                                   tshark_interface=tshark_interface)
        self._start_pcmd_server(ip=ip, port=port, clients=clients)

    def deconfigure_pcmd(self, ip=None, port=None):
        '''
        Stops tshark process then stops Python server.

        :return: None.
        '''
        self._stop_pcmd_collector(ip, port)
        self._stop_pcmd_server(ip, port)
        _ue_id__crnti.clear()

    @keyword("Start collecting PCMD reports")
    def start_collecting_pcmd_reports(self):
        '''
        Reads, parses and saves PCMD reports from tshark output into internal dictionary.

        :return: None.
        '''
        self.logger.debug('Found: {} pcmd collectors, starting collection on all of them'
                          .format(len(self.pcmd_collectors)))
        for pcmd_collector in self.pcmd_collectors:
            pcmd_collector.start_collecting()
        self.logger.debug('All collectors successfully started')

    def start_collecting_pcmd_reports_on_single_tce(self, ip, port):
        '''
        Starting collection for specific pair of ip and port. If not found, error is raised
        '''
        collectors = self._get_collectors(ip, port)
        if not len(collectors):
            raise Exception('Did not find collector matching requested pair: {}:{}, cannot start it.\n'
                            'First use keyword configure_pcmd to start pcmd collector instance'.format(ip, port))
        for pcmd_collector in collectors:
            pcmd_collector.start_collecting()
            self.logger.debug('Started collection on single TCE with pair: {}:{}'.format(ip, port))

    @keyword("Stop collecting PCMD reports")
    def stop_collecting_pcmd_reports(self):
        '''
        Stops reading tshark output but does not stop any process or server.

        :return: None.
        '''
        self.logger.debug('Found: {} pcmd collectors, stopping collection on all of them'
                          .format(len(self.pcmd_collectors)))
        for pcmd_collector in self.pcmd_collectors:
            pcmd_collector.stop_collecting()
        self.logger.debug('All collectors successfully stopped')

    def stop_collecting_pcmd_reports_on_single_tce(self, ip, port):
        '''
        Stopping collection for specific pair of ip and port. If not found, only warning is printed
        '''
        collectors = self._get_collectors(ip, port)
        if not len(collectors):
            r_logger.warn('Did not find collector matching requested pair: {}:{}. Cannot stop it.'.format(ip, port))
        for pcmd_collector in collectors:
            pcmd_collector.stop_collecting()
            self.logger.debug('Stopped collection on single TCE with pair: {}:{}'.format(ip, port))

    @keyword("Clear already collected PCMD reports")
    def clear_already_collected_pcmd_reports(self):
        '''
        Deletes all collected PCMD reports on all started collectors. New reports are still collected.

        :return: None.
        '''
        self.logger.debug('Found: {} pcmd collectors, clearing collected reports on all of them'
                          .format(len(self.pcmd_collectors)))
        for pcmd_collector in self.pcmd_collectors:
            pcmd_collector.clear_collected_messages()
        self.logger.debug('Collected data from all collectors deleted')

    def clear_already_collected_pcmd_reports_on_single_tce(self, ip, port):
        '''
        Deletes all collected PCMD reports on specified tce. New reports are still collected.
        If not found, only warning is printed.

        :return: None.
        '''
        for pcmd_collector in self.pcmd_collectors:
            if str(pcmd_collector.ip) == str(ip) and str(pcmd_collector.port) == str(port):
                pcmd_collector.stop_collecting()
                self.logger.debug('Collected data removed on single TCE with pair: {}:{}'.format(ip, port))
                return
        r_logger.warn('Did not find collector matching requested pair: {}:{}. Cannot clear data.'.format(ip, port))

    @keyword(r"Save C-RNTI of active ${ue_alias:UE_\d+}")
    def save_crnti_for_active_ue_with_alias(self, ue_alias):
        '''
        In PCMD reports, UE is identified by its C-RNTI. This method uses ta_egate_cmd_parser library
        to read C-RNTI of ACTIVE ue on egate and saves it into internal dictionary, so it can be used later.
        This dictionary binds ue_id from provided ue_alias with ue C-RNTI read from egate.

        :param ue_alias:    string that identifies UE.
        :return: None.
        '''
        simulator = self._get_simulator_type_from_ue_alias(ue_alias)

        if simulator == 'wts':
            self._save_ue_crnti_by_ue_alias_by_egate(ue_alias)
        if simulator in ['cus', 'rtg']:
            self._save_ue_crnti_by_ue_alias_by_uexgate(ue_alias)

    @keyword(r"Save C-RNTI of last attached ${ue_alias:UE_\d+}")
    def save_crnti_of_last_atached_ue_with_alias(self, ue_alias):
        '''
        In PCMD reports, UE is identified by its C-RNTI. This method uses PCMD reports to read C-RNTI
        and assign it to provided alias in internal dictionary, so it can be used later. Valid procedure is:
        1) start_collecting_pcmd_reports()
        2) attach first ue (or have one already attached)
        3) save_crnti_of_last_atached_ue_with_alias(...)
        4) attach second ue
        5) save_crnti_of_last_atached_ue_with_alias(...)
        and so on ...

        In other cases this method will raise exception.

        :param ue_alias:    string that identifies UE.
        :return: None.
        '''
        all_pcmd_reports = self.get_all_pcmd_reports()
        field_name = self._get_field_name_by_technology('crnti')
        all_crntis = get_all_field_values_from_pcmd_reports(field_name=field_name,
                                                            pcmd_reports=all_pcmd_reports)
        self._save_ue_crnti_by_ue_alias_by_crnti_from_pcmd_fields(all_crntis, ue_alias)

    def _get_field_name_by_technology(self, field_name):
        '''

        '''
        assert len(self.technologies) == 1, 'Cannot use the keyword if two different technologies are used.\n' \
                                            'Currently configure_pcmd invoked for technologies: {}' \
            .format(self.technologies)
        protocol_per_technology = PROTOCOL[self.technologies[0]]
        return "{}.{}".format(protocol_per_technology, field_name)

    def save_crnti_of_last_atached_ue_with_alias_on_single_tce(self, ue_alias, ip, port):
        '''
        In PCMD reports, UE is identified by its C-RNTI. This method uses PCMD reports to read C-RNTI
        and assign it to provided alias in internal dictionary, so it can be used later. Valid procedure is:
        1) start_collecting_pcmd_reports()
        2) attach first ue (or have one already attached)
        3) save_crnti_of_last_atached_ue_with_alias(...)
        4) attach second ue
        5) save_crnti_of_last_atached_ue_with_alias(...)
        and so on ...

        In other cases this method will raise exception.

        :param ue_alias:    string that identifies UE.
        :return: None.
        '''
        all_pcmd_reports = self.get_all_pcmd_reports(ip, port)
        field_name = self._get_field_name_by_technology('crnti')
        all_crntis = get_all_field_values_from_pcmd_reports(field_name=field_name,
                                                            pcmd_reports=all_pcmd_reports)
        self._save_ue_crnti_by_ue_alias_by_crnti_from_pcmd_fields(all_crntis, ue_alias)

    def _on_timeout(self):
        self.message_awaited.release()
        self.timeout = True

    def set_variable_for_record_yaml(self, variable, value, yaml_path, alias=None, ip=None, port=None):
        '''
        Set value to variable used in yaml file given via yamlpath. When alias is provided,
         it will keep this value only for given alias.
        You can validate your yaml using:
        http://www.yamllint.com/
        before running testcase.
        '''
        self._raise_on_asndecoding_disabled(ip, port)
        set_yaml_variable(yaml_path, variable, value, alias, ip, port)

    def clear_yaml_variables(self, ip=None, port=None):
        '''
        Clear the all saved values for yaml variables.
        '''
        self._raise_on_asndecoding_disabled(ip, port)
        clear_yaml_variables(ip, port)

    def _get_collectors(self, ip=None, port=None):
        filtered_collectors = []
        for pcmd_collector in self.pcmd_collectors:
            if (str(pcmd_collector.ip) == str(ip) or ip is None) and \
               (str(pcmd_collector.port) == str(port) or port is None):
                filtered_collectors.append(pcmd_collector)
        return filtered_collectors

    def _get_servers(self, ip=None, port=None):
        filtered_servers = []
        for pcmd_server in self.pcmd_servers:
            if (str(pcmd_server.ip) == str(ip) or ip is None) and \
               (str(pcmd_server.port) == str(port) or port is None):
                filtered_servers.append(pcmd_server)
        return filtered_servers

