        record_num = int(record_num)
        self.message_awaited = Semaphore(0)
        self.timeout = False
        callback_name = 'await_messages'
        timer = threading.Timer(int(timeout), self._on_timeout)
        messages_counter = [sum([1 if record.asn1per_record_name == record_name else 0
                                 for record in self.get_all_pcmd_reports()])]
        print('Already collected {} record'.format(messages_counter[0]))
        if messages_counter[0] >= record_num:
            print('{} records {} already present in history'.format(record_num, record_name))
            return

        def is_message_expected(pcmd_record):
            if pcmd_record.asn1per_record_name == record_name:
                messages_counter[0] += 1
                if messages_counter[0] == record_num:
                    self.message_awaited.release()
                    timer.cancel()

        start_t = time.time()
        collectors = self._get_collectors(ip, port)
        for pcmd_collector in collectors:
            pcmd_collector.register_callback(callback_name, is_message_expected)
        timer.start()
        print('Awaiting for {} records: {} '.format(record_num, record_name))
        self.message_awaited.acquire()
        for pcmd_collector in collectors:
            pcmd_collector.remove_callback(callback_name)
        print('Awaiting record: {} finished after: {}s'.format(record_name, time.time() - start_t))
        if self.timeout is True:
            raise Exception('Waiting for record: {} timeout after:  {} s'.format(record_name, timeout))

